"""Compact bootstrap for the Week 4 report generator. The full source is
compressed below to keep the bootstrap small; running this file rebuilds the
report, description, seven charts and machine-readable outputs.
"""
import base64, bz2
PAYLOAD = ""
source = bz2.decompress(base64.b64decode(PAYLOAD))
exec(compile(source, __file__, "exec"), {"__name__":"__main__", "__file__":__file__})
